#!/usr/bin/env node
// Usage: node build-compat-bundle.mjs <upstream clone> [output file]
//
// This script makes native/tailwind/assets/compat.js: the plugin layer of
// Tailwind CSS (packages/tailwindcss/src/compat) in one JavaScript file.
// The entry and the shims are in native/tailwind/js. The modules of
// Tailwind CSS that have state are replaced by the shims, which call the
// Rust compiler.
//
// It also makes native/tailwind/assets/script.js: the bundle of the script
// engine, which runs the official compiler of a package `tailwindcss`.
// That bundle has no code of Tailwind CSS (entry: js/script-entry.ts).
import fs from 'node:fs'
import { createRequire } from 'node:module'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

let [upstream, output] = process.argv.slice(2)
if (!upstream) {
  console.error('Usage: node build-compat-bundle.mjs <upstream clone> [output file]')
  process.exit(2)
}
upstream = path.resolve(upstream)

let here = path.dirname(fileURLToPath(import.meta.url))
let root = path.resolve(here, '../../..')
let js = path.join(root, 'native/tailwind/js')
let src = path.join(upstream, 'packages/tailwindcss/src')
output = path.resolve(output ?? path.join(root, 'native/tailwind/assets/compat.js'))

let version = JSON.parse(fs.readFileSync(path.join(upstream, 'packages/tailwindcss/package.json'), 'utf8')).version

let esbuild = loadEsbuild()

// esbuild: from the node_modules of this directory (package.json), or from
// the pnpm store of the upstream clone.
function loadEsbuild() {
  let candidates = [path.join(here, 'package.json'), path.join(upstream, 'package.json')]
  let store = path.join(upstream, 'node_modules/.pnpm')
  if (fs.existsSync(store)) {
    for (let name of fs.readdirSync(store).sort()) {
      if (/^esbuild@\d/.test(name)) candidates.push(path.join(store, name, 'node_modules/esbuild/package.json'))
    }
  }
  for (let candidate of candidates) {
    try {
      return createRequire(candidate)('esbuild')
    } catch {}
  }
  console.error('build-compat-bundle.mjs: esbuild is not there. Run "npm install" in tests/upstream/tools.')
  process.exit(1)
}

// The modules of Tailwind CSS that a shim replaces.
let replaced = new Map([
  [path.join(src, 'index.ts'), path.join(js, 'shims/index.ts')],
  [path.join(src, 'theme.ts'), path.join(js, 'shims/theme.ts')],
  [path.join(src, 'apply.ts'), path.join(js, 'shims/apply.ts')],
  [path.join(src, 'css-functions.ts'), path.join(js, 'shims/css-functions.ts')],
  [path.join(src, 'compat/legacy-utilities.ts'), path.join(js, 'shims/legacy-utilities.ts')],
])

// The modules of Tailwind CSS that must not be in the bundle: a shim has
// their work.
let forbidden = ['design-system.ts', 'compile.ts', 'at-import.ts', 'property-order.ts'].map((file) =>
  path.join(src, file),
)

let shims = {
  name: 'shims',
  setup(build) {
    build.onResolve({ filter: /^tailwindcss-src\// }, (args) => {
      let file = path.join(src, args.path.slice('tailwindcss-src/'.length) + '.ts')
      return { path: replaced.get(file) ?? file }
    })
    build.onResolve({ filter: /^\./ }, (args) => {
      if (!args.resolveDir.startsWith(src)) return null
      let file = path.resolve(args.resolveDir, args.path)
      if (fs.existsSync(file) && fs.statSync(file).isDirectory()) file = path.join(file, 'index')
      if (!file.endsWith('.ts')) file += '.ts'
      let shim = replaced.get(file)
      return shim ? { path: shim } : null
    })
  },
}

let result = await esbuild.build({
  entryPoints: [path.join(js, 'entry.ts')],
  bundle: true,
  format: 'iife',
  platform: 'neutral',
  target: 'es2022',
  minify: true,
  legalComments: 'none',
  write: false,
  metafile: true,
  plugins: [shims],
  define: { 'process.env.NODE_ENV': '"production"', 'process.env.FEATURES_ENV': '"stable"' },
})

let inputs = Object.entries(result.metafile.outputs[Object.keys(result.metafile.outputs)[0]].inputs)
for (let [file, info] of inputs) {
  if (info.bytesInOutput === 0) continue
  let absolute = path.resolve(file)
  if (forbidden.includes(absolute)) {
    console.error(`build-compat-bundle.mjs: ${file} is in the bundle. Add a shim for the import that needs it.`)
    process.exit(1)
  }
}

let header = `// Generated by tests/upstream/tools/build-compat-bundle.mjs. Do not edit.
// The plugin layer of Tailwind CSS v${version} (packages/tailwindcss/src/compat,
// MIT License, Copyright (c) Tailwind Labs, Inc.), with the shims of
// native/tailwind/js.
`
fs.writeFileSync(output, header + result.outputFiles[0].text)

// The bundle of the script engine, next to the first bundle.
let scriptOutput = path.join(path.dirname(output), 'script.js')
let scriptResult = await esbuild.build({
  entryPoints: [path.join(js, 'script-entry.ts')],
  bundle: true,
  format: 'iife',
  platform: 'neutral',
  target: 'es2022',
  minify: true,
  legalComments: 'none',
  write: false,
  metafile: true,
})
for (let file of Object.keys(scriptResult.metafile.inputs)) {
  if (path.resolve(file).startsWith(upstream + path.sep)) {
    console.error(`build-compat-bundle.mjs: ${file} is in the script bundle. It must have no code of Tailwind CSS.`)
    process.exit(1)
  }
}
fs.writeFileSync(
  scriptOutput,
  `// Generated by tests/upstream/tools/build-compat-bundle.mjs. Do not edit.
// The runtime of the script engine (native/tailwind/js/script-entry.ts).
` + scriptResult.outputFiles[0].text,
)
console.error(`build-compat-bundle.mjs: wrote ${scriptOutput} (${fs.statSync(scriptOutput).size} bytes)`)

if (process.env.VERBOSE) {
  for (let [file, info] of inputs.sort((a, z) => z[1].bytesInOutput - a[1].bytesInOutput)) {
    console.error(String(info.bytesInOutput).padStart(8), path.relative(upstream, path.resolve(file)))
  }
}
console.error(`build-compat-bundle.mjs: wrote ${output} (${fs.statSync(output).size} bytes)`)
